class Solution {
public:
    int matrixScore(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        int score = m * (1 << (n - 1));
        for (int j = 1; j < n; j++) {
            int ones = 0;
            for (int i = 0; i < m; i++) {
                int bit = grid[i][0] == 0 ? 1 - grid[i][j] : grid[i][j];
                ones += bit;
            }
            int best = ones > m - ones ? ones : m - ones;
            score += best * (1 << (n - 1 - j));
        }
        return score;
    }
};
